/* @lc app=leetcode id=2959 lang=kotlin */ class Solution { fun numberOfSets(n: Int, maxDistance: Int, roads: Array<IntArray>): Int = (0 until (1 shl n)).count { mask -> Array(n) { i -> IntArray(n) { j -> if (i == j) 0 else 100000000 } }.also { d -> roads.forEach { r -> if (((mask shr r[0]) and 1 != 0) && ((mask shr r[1]) and 1 != 0)) d[r[0]][r[1]] = minOf(d[r[0]][r[1]], r[2]).also { d[r[1]][r[0]] = minOf(d[r[1]][r[0]], r[2]) } } }.also { d -> (0 until n).forEach { k -> if ((mask shr k) and 1 != 0) (0 until n).forEach { i -> if ((mask shr i) and 1 != 0) (0 until n).forEach { j -> if ((mask shr j) and 1 != 0) d[i][j] = minOf(d[i][j], d[i][k] + d[k][j]) } } } }.let { d -> (0 until n).all { i -> (mask shr i) and 1 == 0 || (0 until n).all { j -> (mask shr j) and 1 == 0 || d[i][j] <= maxDistance } } } } }